<?php

namespace nyu\Runs\Shows;

use nyu\App\Actionset;
use nyu\Data\DBCon;
use nyu\Data\DBLst;
use nyu\Data\DBRec;
use nyu\Data\DBStore\Filter;

/**
 * Shows: the records of the table shows, and its events and items.
 * Generated by makerun from runspec.json; "php nyuRun makerun fromSpec Shows"
 * writes it again, over any change made by hand.
 *
 *   GET    /shows                     index
 *   POST   /shows                     create
 *   GET    /shows/<id>                view
 *   PUT    /shows/<id>                update
 *   DELETE /shows/<id>                remove
 *   GET    /shows/<id>/events         events
 */
class Actions extends Actionset {

	// The database (its label, '' for the default one), the table, its key, and the fields read and written with their format
	const BASE_LINK = '';
	const TBLE_NAME = 'shows';
	const IDNT_COLN = 'id_show';
	const FLDS_LIST = Array('title'=>'', 'venue'=>'');
	// The children: the field naming their record, the fields read, their order, and whether the list holds them
	const CHLD_LIST = Array('events'=>Array('linkedBy'=>'show_id', 'fieldSet'=>Array('id_event', 'date', 'time'), 'sortedBy'=>'^date', 'listsToo'=>true), 'items'=>Array('linkedBy'=>'show_id', 'fieldSet'=>Array('type'), 'sortedBy'=>'', 'listsToo'=>false));

	/**
	 * Asks for the least role of the Run before every action.
	 */
	protected function openEachAction(): Void {
		$this->needsActionRle('standard');
	}

	/**
	 * Lists the records: filtered on the fields sent under filters, each
	 * matched anywhere in the field as it is written (a star is a star),
	 * sorted by sortedBy (a field, ^ before it for the reverse order),
	 * paged by limitVal and rowIndex. The children the list holds are read
	 * at once for the page, one query for each child table.
	 */
	public function index(): Void {
		$listInst = new DBLst( self::TBLE_NAME, null, null, null, null, DBCon::linkNamedDbCon(self::BASE_LINK) );
		$listInst->setReadColumns( implode(', ', array_merge(Array(self::IDNT_COLN), array_keys(self::FLDS_LIST))) );
		$fltrsDct = Array();
		foreach( (array)$this->inputsRegr->readValueByKey('filters') as $oneFld => $oneVal ){
			if( isset(self::FLDS_LIST[$oneFld]) && is_scalar($oneVal) && strval($oneVal)!=='' ){
				$fltrsDct[$oneFld.'~'] = '*'.Filter::quoteMatchText(strval($oneVal)).'*';
			}
		}
		$listInst->setListFilters($fltrsDct);
		$sortText = strval( $this->inputsRegr->readValueByKey('sortedBy') ?? '' );
		$listInst->setOrderFields( (ltrim($sortText, '^')===self::IDNT_COLN || isset(self::FLDS_LIST[ltrim($sortText, '^')])) ? $sortText : self::IDNT_COLN );
		$listInst->setLimitOffset( Array($this->inputsRegr->readValueByKey('limitVal') ?? '', $this->inputsRegr->readValueByKey('rowIndex') ?? '') );
		$rowsList = $listInst->readRowsOfList();
		if( !is_array($rowsList) ){
			$this->stopThisAction(500, 'The list cannot be read');
		}
		$keysList = array_column($rowsList, self::IDNT_COLN);
		foreach( self::CHLD_LIST as $oneTbl => $oneSet ){
			if( $oneSet['listsToo'] ){
				$childRow = $this->readChildRecds($oneTbl, $keysList);
				foreach( $rowsList as $nthRow => $oneRow ){
					$rowsList[$nthRow][$oneTbl] = $childRow[$oneRow[self::IDNT_COLN]] ?? Array();
				}
			}
		}
		$this->checkActionLst($rowsList);
	}

	/**
	 * Gives a record, with its children nested.
	 *
	 * @param String $recordIdText The key of the record, from the path.
	 */
	public function view( String $recordIdText='' ): Void {
		$rcrdVals = $this->readRecordById($recordIdText)[1];
		foreach( array_keys(self::CHLD_LIST) as $oneTbl ){
			$rcrdVals[$oneTbl] = $this->readChildRecds($oneTbl, Array($rcrdVals[self::IDNT_COLN]))[$rcrdVals[self::IDNT_COLN]] ?? Array();
		}
		$this->statusCode = 200;
		$this->replyValue = $rcrdVals;
	}

	/**
	 * Adds a record from the fields sent: a 201 with its key.
	 */
	public function create(): Void {
		$sentVals = $this->readSentFields();
		$rcrdInst = new DBRec( self::TBLE_NAME, Array(), Array(), DBCon::linkNamedDbCon(self::BASE_LINK) );
		$rcrdInst->setFieldsArray($sentVals);
		$savedKey = $rcrdInst->insertOrUpdate();
		if( $savedKey===false ){
			$this->stopThisAction(500, 'The record cannot be saved');
		}
		$this->statusCode = 201;
		$this->replyValue = Array(self::IDNT_COLN=>$savedKey);
	}

	/**
	 * Changes the fields sent of a record: a 200 with the record as saved.
	 *
	 * @param String $recordIdText The key of the record, from the path.
	 */
	public function update( String $recordIdText='' ): Void {
		$rcrdInst = $this->readRecordById($recordIdText)[0];
		$rcrdInst->setFieldsArray( $this->readSentFields() );
		if( $rcrdInst->insertOrUpdate()===false ){
			$this->stopThisAction(500, 'The record cannot be saved');
		}
		$this->statusCode = 200;
		$this->replyValue = $this->readRecordById($recordIdText)[1];
	}

	/**
	 * Removes a record: a 204. Its children are left as they are.
	 *
	 * @param String $recordIdText The key of the record, from the path.
	 */
	public function remove( String $recordIdText='' ): Void {
		if( !$this->readRecordById($recordIdText)[0]->dropThisRecord() ){
			$this->stopThisAction(500, 'The record cannot be removed');
		}
		$this->statusCode = 204;
	}

	/**
	 * Lists the events of a record.
	 *
	 * @param String $recordIdText The key of the record, from the path.
	 */
	public function events( String $recordIdText='' ): Void {
		$rcrdClef = $this->readRecordById($recordIdText)[1][self::IDNT_COLN];
		$this->checkActionLst( $this->readChildRecds('events', Array($rcrdClef))[$rcrdClef] ?? Array() );
	}

	/**
	 * Reads a record by its key: the request ends with a 404 when there is none.
	 *
	 * @param String $recordIdText The key of the record, from the path.
	 * @return Array The record, loaded, then its key and fields.
	 */
	protected function readRecordById( String $recordIdText ): Array {
		$rcrdInst = new DBRec( self::TBLE_NAME, Array(), Array(), DBCon::linkNamedDbCon(self::BASE_LINK) );
		$rcrdVals = ($recordIdText==='') ? false : $rcrdInst->loadRecordList($recordIdText);
		if( !is_array($rcrdVals) ){
			$this->stopThisAction(404, 'Not Found');
		}
		return Array( $rcrdInst, array_intersect_key($rcrdVals, array_flip(array_merge(Array(self::IDNT_COLN), array_keys(self::FLDS_LIST)))) );
	}

	/**
	 * Gives the fields the request sent. A field given a format whose value
	 * is empty was not valid, and a request sending no field is empty: both
	 * are refused with a 400.
	 *
	 * @return Array The values, by field.
	 */
	protected function readSentFields(): Array {
		$sentVals = Array();
		$badField = Array();
		foreach( self::FLDS_LIST as $oneFld => $oneFmt ){
			$sentValu = $this->inputsRegr->readValueByKey($oneFld);
			if( $sentValu===null ){
				continue;
			}
			if( is_array($sentValu) || ($oneFmt!=='' && strval($sentValu)==='') ){
				$badField[] = $oneFld;
			}
			$sentVals[$oneFld] = $sentValu;
		}
		if( !empty($badField) || empty($sentVals) ){
			$this->stopThisAction(400, 'Missing or invalid input: '.(empty($badField) ? 'no field sent' : implode(', ', $badField)));
		}
		return $sentVals;
	}

	/**
	 * Reads the children of some records at once, in one query.
	 *
	 * @param String $childTbleTxt The child table, as CHLD_LIST names it.
	 * @param Array  $parentKeyLst The keys of the records.
	 * @return Array The children, by the key of their record.
	 */
	protected function readChildRecds( String $childTbleTxt, Array $parentKeyLst ): Array {
		$childDct = self::CHLD_LIST[$childTbleTxt];
		if( empty($parentKeyLst) ){
			return Array();
		}
		$listInst = new DBLst( $childTbleTxt, null, null, null, null, DBCon::linkNamedDbCon(self::BASE_LINK) );
		$listInst->setReadColumns( implode(', ', array_unique(array_merge(Array($childDct['linkedBy']), $childDct['fieldSet']))) );
		$listInst->setListFilters( Array($childDct['linkedBy']=>array_values($parentKeyLst)) );
		if( $childDct['sortedBy']!=='' ){
			$listInst->setOrderFields($childDct['sortedBy']);
		}
		$rowsList = $listInst->readRowsOfList();
		if( !is_array($rowsList) ){
			$this->stopThisAction(500, 'The children cannot be read');
		}
		$childRow = Array();
		foreach( $rowsList as $oneRow ){
			$childRow[$oneRow[$childDct['linkedBy']]][] = $oneRow;
		}
		return $childRow;
	}

}
